def merge_shard_candidates(shard_results: list[list[tuple]], top_k: int = 200) -> list[tuple]:
    merged = []
    for res in shard_results:
        merged.extend(res)
    merged.sort(key=lambda x: x[1], reverse=True)
    return merged[:top_k]

def hydrate_features(feature_store, doc_ids: list[str], user_ctx: dict) -> list[dict]:
    doc_feats = feature_store.mget_docs(doc_ids)
    return [{**doc_feats.get(did, {}), 'user_tier': user_ctx.get('tier', 0)} for did in doc_ids]

def dcg_at_k(relevances: list[float], k: int = 10) -> float:
    import math
    return sum((2 ** rel - 1) / math.log2(idx + 2) for idx, rel in enumerate(relevances[:k]))

def mmr_diversify(candidates: list[dict], sim_fn, lambda_rel: float = 0.7, top_n: int = 20) -> list[dict]:
    selected, pool = [], list(candidates)
    while pool and len(selected) < top_n:
        best = max(pool, key=lambda c: lambda_rel * c['score'] - (1 - lambda_rel) * max((sim_fn(c, s) for s in selected), default=0.0))
        selected.append(best); pool.remove(best)
    return selected

def ips_weighted_ctr(clicks: list[tuple[int, float]]) -> float:
    # Each item is (clicked 0|1, position_propensity)
    return sum(c / max(0.05, p) for c, p in clicks) / max(1, len(clicks))
